"""Frozen G03: common improvement versus newly hit wrong first layers, no new optimization."""
from geometry021 import *
from visualize021 import layer,composite,free_camera,panel,plt,finish,body_layer,edge

def main():
 group='G03';conf,src=group_data(group);b=dict(np.load(conf['bodies']['B2']['path']));rv=np.load(conf['ring']['path']);rows=[]
 for a in src:
  d=np.load(R/'evaluation/groups'/group/(a['id']+'_SOURCE_EVIDENCE.npz'));ix=np.flatnonzero(d['gained']);z=d['B2_depth_mm'][ix];dir=np.c_[a['obs']['uv'][ix],np.ones(len(ix))]@np.linalg.inv(a['obs']['K']).T;point=a['C'][:3,3]+(dir*z[:,None])@a['C'][:3,:3].T
  for j,k in enumerate(ix):rows.append(dict(source=a['id'],role=a['role'],native_pixel_id=int(a['obs']['pixel_id'][k]),u=int(a['obs']['uv'][k,0]),v=int(a['obs']['uv'][k,1]),original_HERO_face_id=int(a['obs']['face_id'][k]),B2_visible_body_face_id=int(d['B2_body_face_id'][k]),HERO_XYZ_mm=a['X'][k],B2_first_hit_XYZ_mm=point[j],HERO_depth_mm=float(a['obs']['z'][k]),B2_depth_mm=float(z[j]),signed_axial_difference_mm=float(z[j]-a['obs']['z'][k]),absolute_axial_difference_mm=float(abs(z[j]-a['obs']['z'][k])),not_GT=True))
 save('metrics/groups/G03_NEW_HIT_FAILURE_LOCATIONS.json',rows);table('metrics/groups/G03_NEW_HIT_FAILURE_LOCATIONS.csv',rows);top=sorted(rows,key=lambda a:a['absolute_axial_difference_mm'],reverse=True)[:12];bounds=np.r_[rv['V'],*[a['V'][np.unique(a['F'])]for a in src],b['V']];view=free_camera(bounds,10,-105);base=[layer(a['V'],a['F'],'#60ad9d',a['id'])for a in src]+[layer(rv['V'],rv['F'],'black','CAD')];badfaces={a['B2_visible_body_face_id']for a in top};fc=np.tile([.4,.6,.9],(len(b['F_solid']),1));lookup={tuple(f):i for i,f in enumerate(b['F'])}
 for i,f in enumerate(b['F_solid']):
  if lookup.get(tuple(f),-1)in badfaces:fc[i]=[.95,.1,.15]
 body=layer(b['V'],b['F_solid'],fc,'B2');lines=[]
 for a in top:
  p,q=a['HERO_XYZ_mm'],a['B2_first_hit_XYZ_mm'];m=trimesh.creation.cylinder(radius=.025,segment=np.array([p,q]),sections=6);lines.append(layer(m.vertices,m.faces,'red','actual ray error segment'))
 fig,axs=plt.subplots(2,2,figsize=(14,11));panel(axs[0,0],composite(base),view,bounds,'All original G03 TRUSTED HERO + black CAD\nNo cleanup, no deformation, no ICP');panel(axs[0,1],composite(base+[body]+lines),view,bounds,'Actual newly-hit first-layer errors on fixed native rays\nRed segments: HERO position → actual B2 first hit, worst12 diagnostic')
 s=next(a for a in src if a['id']==top[0]['source']);cache=np.load(s['cache']);axs[1,0].imshow(cache['RGB']);edge(axs[1,0],cache['labels']==1,'lime');points=[a for a in rows if a['source']==s['id']];uv=np.array([[a['u'],a['v']]for a in points]);p=np.c_[uv,np.ones(len(uv))]@np.linalg.inv(s['obs']['K']).T@cache['K'].T;p=p[:,:2]/p[:,2:];im=axs[1,0].scatter(p[:,0],p[:,1],c=[a['absolute_axial_difference_mm']for a in points],s=3,cmap='magma',vmin=0,vmax=10);fig.colorbar(im,ax=axs[1,0],shrink=.6,label='actual |dz| mm, display 0..10');axs[1,0].set_title(s['id']+' actual RGB / full Mask\nAll newly hit original native Pixel IDs mapped by K');axs[1,0].axis('off')
 pooled=load(R/'metrics/groups/G03_EXACT_COMMON_GAINED_LOST.json');x=np.arange(2);ax=axs[1,1];ax.bar(x-.25,[a['common_B0_error_mm']['MAE']for a in pooled[:2]],.25,label='common B0');ax.bar(x,[a['common_B2_error_mm']['MAE']for a in pooled[:2]],.25,label='common B2');ax.bar(x+.25,[a['gained_B2_error_mm']['MAE']for a in pooled[:2]],.25,label='gained B2');ax.set_xticks(x,['FIT','HOLDOUT']);ax.set_ylabel('native HERO |dz| MAE mm, not GT');ax.legend();ax.grid(axis='y',alpha=.2)
 fig.suptitle('G03 fixed-denominator diagnosis: more body hits do NOT guarantee recovered long-stalk geometry\nCommon rays improve, but gained FIT/HOLDOUT rays average 7.20/7.82mm error. Independent raw source disagreements remain.\nRed segments and face IDs are actual calculations, not suggested optimization updates; predictions are unchanged.');fig.tight_layout(rect=[0,0,1,.91]);finish(fig,'groups/G03/New_First_Hits_Are_Not_Correct_Surface.png',125);save('runtime/G03_GAIN_DIAGNOSTIC_COMPLETE.json',dict(epoch=time.time(),gained_original_rays_N=len(rows)));print('G03_GAIN_DIAGNOSTIC_COMPLETE',len(rows),flush=True)
if __name__=='__main__':main()
